/** 앱 내 알림을 저장합니다. */
package com.dandimate.durooduroo.notification.domain;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="notifications") public class Notification { @Id private String id; @Column(nullable=false) private String memberId; @Column(nullable=false) private String type; @Column(nullable=false) private String resourceType; @Column(nullable=false) private String resourceId; private LocalDateTime readAt; @Column(nullable=false) private LocalDateTime createdAt; protected Notification(){} private Notification(String m,String t,String rt,String ri){id=UUID.randomUUID().toString();memberId=m;type=t;resourceType=rt;resourceId=ri;createdAt=LocalDateTime.now();} public static Notification create(String m,String t,String rt,String ri){return new Notification(m,t,rt,ri);} public void read(){readAt=LocalDateTime.now();} public String getId(){return id;} public String getMemberId(){return memberId;} public String getType(){return type;} public String getResourceType(){return resourceType;} public String getResourceId(){return resourceId;} public LocalDateTime getReadAt(){return readAt;} public LocalDateTime getCreatedAt(){return createdAt;} }
